vector<vector<int>> threeSum(vector<int>& a) {
    sort(a.begin(), a.end()); vector<vector<int>> out; int n = a.size();
    for (int i = 0; i + 2 < n; i++) {
        if (i && a[i] == a[i - 1]) continue;
        int j = i + 1, k = n - 1;
        while (j < k) {
            int s = a[i] + a[j] + a[k];
            if (s < 0) j++; else if (s > 0) k--;
            else { out.push_back({a[i], a[j], a[k]}); j++; while (j < k && a[j] == a[j - 1]) j++; k--; }
        }
    }
    return out;
}
